import math

def calculate_ratio(n):
    if n < 4:
        return 0
    f = math.comb(n, 3)
    g = math.comb(n, 4)
    return (g**3) / (f**4)

print(f"3/32 = {3/32}")
print(f"27/1280 = {27/1280}")

for n in range(4, 50):
    ratio = calculate_ratio(n)
    if ratio > 27/1280:
        print(f"n={n}, ratio={ratio} > 27/1280")
        break
